"""Build reproducible charts and a local interactive review from saved study outputs."""
import json, html
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parent
r=json.loads((R/'ratings.json').read_text()); m=json.loads((R/'manifest.json').read_text())
s=r['summary']; names=[x['condition'] for x in s]; cases=list(r['cases'])
fig,ax=plt.subplots(figsize=(12,9)); y=np.arange(len(s))
ax.barh(y+.17,[x['mostly_correct_available'] for x in s],height=.32,label='Best candidate after visual review',color='#aec9db')
ax.barh(y-.17,[x['mostly_correct_model_top'] for x in s],height=.32,label='SAM highest estimated IoU',color='#27658a')
ax.set_yticks(y,names);ax.invert_yaxis();ax.set_xlim(0,7.5);ax.set_xticks(range(8));ax.set_xlabel('Views graded mostly correct (visual grade ≥4), out of seven')
ax.set_title('Pipette point-prompt study: more clicks did not consistently help\nSingle AI reviewer; no ground-truth masks; fixed box and full-image encoding')
ax.legend(loc='lower right');ax.grid(axis='x',alpha=.2);fig.tight_layout()
for ext in ['png','svg']:fig.savefig(R/f'results-chart.{ext}',dpi=180)
plt.close(fig)
fig,axes=plt.subplots(2,1,figsize=(16,8),layout='constrained')
for ax,key,title in zip(axes,['model_top_visual_grade','best_of_four_visual_grade'],['Model top candidate','Best of four after visual review']):
 a=np.array([[r['cases'][cid]['conditions'][n][key] for n in names] for cid in cases]);im=ax.imshow(a,vmin=1,vmax=5,cmap='RdYlGn',aspect='auto');ax.set_yticks(range(len(cases)),cases);ax.set_xticks(range(len(names)),names,rotation=50,ha='right');ax.set_title(title)
 for i in range(len(cases)):
  for j in range(len(names)):ax.text(j,i,str(a[i,j]),ha='center',va='center',fontsize=9)
fig.colorbar(im,ax=axes,label='Visual grade (1 wrong/failed → 5 clean approximate)',shrink=.7)
fig.savefig(R/'case-grades.png',dpi=160);plt.close(fig)
data={'ratings':r,'manifest':m}; payload=json.dumps(data).replace('</','<\\/')
page='''<!doctype html><html><head><meta charset="utf-8"><title>Pipette prompt study</title><style>body{font:16px system-ui;background:#13202b;color:#e6edf2;max-width:1700px;margin:24px auto;padding:16px}select,button{padding:8px;margin:6px;background:#243747;color:white;border:1px solid #6d8494}img{max-width:100%;background:#182b38}a{color:#83c7ef}.note{padding:12px;background:#243747}.cols{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}h1{font-size:26px}small{color:#bad0df}</style></head><body><h1>Pipette point-prompt study</h1><p>Seven representative views • 19 prompt conditions • 532 candidate masks directly inspected. Ratings are qualitative judgments by one AI reviewer, not measured IoU.</p><p>Best tested default: good box + body and exposed-shaft positives + one targeted negative. Stop earlier if the mask is already good.</p><label>View <select id="case"></select></label><label>Prompt <select id="condition"></select></label><button id="prev">Previous prompt</button><button id="next">Next prompt</button><p id="detail" class="note"></p><p id="note"></p><p><small>Sheet columns: original with green positives / red negatives; candidates c0–c3. TOP refers to SAM's highest estimated IoU. Cyan is the predicted mask.</small></p><img id="sheet"><div class="cols"><section><h3>Original</h3><img id="original"></section><section><h3>Model top binary mask</h3><img id="top"></section><section><h3>Visually selected binary mask</h3><img id="best"></section></div><p><a id="placement">Enlarged point-placement audit</a> · <a href="README.md">Methods and findings</a> · <a href="ratings.csv">All ratings (CSV)</a> · <a href="manifest.json">Inference manifest</a></p><h2>Aggregates</h2><img src="results-chart.png"><img src="case-grades.png"><script>const DATA=PAYLOAD;const C=document.getElementById('case'),N=document.getElementById('condition');for(const c of Object.keys(DATA.ratings.cases))C.add(new Option(c,c));for(const r of DATA.ratings.summary)N.add(new Option(r.condition,r.condition));N.value='p2-body-shaft-n1';function update(){let cid=C.value,n=N.value,rc=DATA.ratings.cases[cid],v=rc.conditions[n],mc=DATA.manifest.cases[cid],p=mc.conditions[n].prompt;document.getElementById('detail').textContent=`${p.fg.length} positives + ${p.bg.length} negatives; ${p.point_only?'no box':'box included'}. Model top c${v.model_top_candidate_index}: grade ${v.model_top_visual_grade}/5. Visually selected c${v.selected_candidate_index}: grade ${v.best_of_four_visual_grade}/5.`;document.getElementById('note').textContent=rc.note;document.getElementById('sheet').src=`${cid}/${n}.jpg`;document.getElementById('original').src=`../every100-review/${mc.case.source_frame}/${mc.case.view}-original.png`;for(const k of ['top','best'])document.getElementById(k).src=`${cid}/results/masks/${n}_candidate-${String(v[k==='top'?'model_top_candidate_index':'selected_candidate_index']).padStart(2,'0')}.png`;document.getElementById('placement').href=`${cid}-placement.png`;}C.onchange=N.onchange=update;document.getElementById('next').onclick=()=>{N.selectedIndex=(N.selectedIndex+1)%N.options.length;update()};document.getElementById('prev').onclick=()=>{N.selectedIndex=(N.selectedIndex+N.options.length-1)%N.options.length;update()};update();</script></body></html>'''.replace('PAYLOAD',payload)
(R/'review.html').write_text(page)
lines=['# Pipette point-prompt mini study','', 'The best tested default is a good box, two positives (body interior and exposed opaque shaft), and one targeted negative on a nearby confuser: three points total, plus the box. This is a preliminary recipe for these views, not a universal optimum.','', '## Practical guidance','', '1. Check the box first. Include the visible pipette and exclude neighbouring pipettes where possible. A good box alone worked well on the clear resting controls.', '2. Start with one positive inside the clearly visible body. Avoid the silhouette boundary, glove, uncertain transparent tip, and occluded parts.', '3. Add a positive near the centre of an exposed shaft segment if the shaft is missing. Do not place points on the support tube or infer hidden shaft pixels.', '4. Place a negative inside an unwanted object actually included by the mask, such as the glove, rack, or neighbouring pipette. Prefer the interior of that error region over an arbitrary background point.', '5. Add a cap/hook point only when it is clearly visible and missing. Cap-only prompting was weaker here, particularly in a small occluded cap view.', '6. Inspect all candidates if practical. Stop once the visible object is represented well; blindly adding five or eight positives often made masks worse.', '', '## Results', '', '“Mostly correct” means visual grade 4 or 5; grade 4 can still include small errors or an uncertain tip and does not mean production-ready.', '', '| Condition | Positives / negatives | Mostly correct, model top / 7 | Mostly correct, visual best / 7 |','|---|---:|---:|---:|']
for row in s:lines.append(f"| {row['condition']} | {row['positive_points']} / {row['negative_points']} | {row['mostly_correct_model_top']} | {row['mostly_correct_available']} |")
lines += ['', 'The two-positive/one-negative recipe gave a mostly correct model-top mask in six of seven views. Body-only gave three of seven model-top masks, despite six of seven views having a better available candidate. This candidate-ranking gap matters: prompt quality should be judged on the mask the workflow actually chooses, not only the best mask found after manual inspection.', '', 'One body positive plus one negative also performed well (five of seven model-top masks). Adding three negatives to the body/shaft pair gave four of seven, versus six with one negative. More negatives are therefore not automatically better; use them to correct specific remaining errors.', '', 'Remaining problems: frame 100 T2 still has rack/shaft ambiguity; frame 500 T1 still has support-tube contamination; the crowded frame 0 T1 has neighbouring-pipette flecks. Transparent distal-tip boundaries remain uncertain. None of these findings proves downstream tracking accuracy.', '', '## Method and limitations', '', 'Seven hard-biased views from one recording and one blue pipette: frames 0 (T2, T1, FPV), 100 (T2), 200 (T4), 300 (T3), and 500 (T1). The samples are correlated and do not cover every camera, pipette colour, or pose. No held-out test set or human ground-truth masks were used.', '', 'Local SAM3.1 multiplex checkpoint; original full-frame images encoded at maximum side length 1280; the same box was held fixed within each view except explicit points-only conditions. All points were manually chosen on enlarged originals. Each of 19 conditions was decoded independently with all its points supplied simultaneously. No previous mask logits were fed back. Display crops are for review only, not inference. There were 133 decodes and four masks per decode, totalling 532 directly reviewed candidates.', '', 'A follow-up of three simpler recipes was added after inspecting the original 16 conditions. This adaptive design makes the winner exploratory; validate it on unseen views before adopting a fixed policy. The extra five/eight-positive conditions densify visible parts and are not an experiment in eight sequential corrective clicks.', '', 'Grades: 1 wrong/failed; 2 major non-target inclusion; 3 notable leakage/missing part; 4 mostly correct with small errors or uncertain tip; 5 clean approximate visible pixels. One AI reviewer inspected all candidate sheets against the originals. The review was not blinded. Model-top means highest estimated IoU score, not measured IoU. Best-of-four is an optimistic manual-selection comparison.', '', 'All 532 masks were checked for native image dimensions and binary values. Full-frame inspection of the winning recipe found no mask pixels outside the display crops. A separate outside-crop audit is in validation.json; other conditions contain small remote islands, largest 380 pixels. Production labels and tracking settings were not changed.', '', '## General SAM guidance', '', '[The original SAM paper](https://arxiv.org/html/2304.02643v1) uses interior first clicks and corrective clicks inside false-positive or false-negative regions. Its reported diminishing returns around eight iteratively sampled points includes previous-mask feedback; that does not establish eight simultaneous positive clicks as an optimal recipe for these pipettes. The body/shaft/negative recommendation is our inference from this local comparison.', '', '## Review and reproduce', '', '- Open review.html to switch view and prompt, compare all four candidates with the original, and inspect full-resolution binary masks.', '- results-chart.png / .svg: aggregate counts; case-grades.png: every case and condition.', '- design.py and design.json: point locations and fixed conditions.', '- run.py: inference; rate.py: explicit visual judgments; report.py: these deliverables.', '- manifest.json records source hashes, prompts, candidate scores and model selection; ratings.csv contains all 133 ratings.', '', 'These are study outputs only. No masks from this experiment have been promoted into the existing annotation set.']
(R/'README.md').write_text('\n'.join(lines)+'\n')
print('Wrote review.html, README.md, charts')
